def declarations():
    return {p: re.findall(r'^\s*(?:noncomputable\s+)?(theorem|lemma|def|abbrev|instance)\s+([A-Za-z][A-Za-z0-9_\.]*)', old.lean_code(read(p)), re.M) for p in MODULES}


def register():
    baseline = obj(PREFIX + '-baseline.json')
    assert len(baseline['files']) == 1192
    assert all(digest(f['path']) == f['sha256'] for f in baseline['files'])
    ds = declarations()
    names = ['Hindman168.' + name for p, values in ds.items() for _, name in values]
    assert len(names) == len(set(names)) == 13
    assert sum(kind in {'theorem', 'lemma'} for values in ds.values() for kind, _ in values) == 9
    root, registry = read('Hindman168.lean'), read('Verification.lean')
    for path in MODULES:
        line = 'import ' + path[:-5].replace('/', '.')
        assert line not in root.splitlines()
        root += '\n' + line + '\n'
    for name in names:
        line = '#print axioms ' + name
        assert line not in registry.splitlines()
        registry += '\n' + line + '\n'
    Path('Hindman168.lean').write_text(root, encoding='utf-8')
    Path('Verification.lean').write_text(registry, encoding='utf-8')
    write(PREFIX + '-registration.json', {'baseline_hash_count': 1192, 'modules': MODULES,
        'names': names, 'theorem_count': 9, 'selected_report_count': 13, 'declarations': ds})
    print(json.dumps({'registered': len(names), 'modules': len(MODULES)}))


def run_build(kind):
    command = ['lake', 'build'] if kind == 'build' else ['lake', 'env', 'lean', 'Verification.lean']
    if kind == 'kernel':
        result = obj(PREFIX + '-build-result.json')
        assert result['terminal'] and result['exit_code'] == 0
        assert result['log_sha256'] == digest(PREFIX + '-build.txt')
    log = PREFIX + ('-build.txt' if kind == 'build' else '-axioms.txt')
    start = time.monotonic()
    with open(log, 'wb') as stream:
        result = subprocess.run(command, stdout=stream, stderr=subprocess.STDOUT)
    record = dict(command=command, exit_code=result.returncode, terminal=True,
                  elapsed_seconds=time.monotonic() - start, log_sha256=digest(log))
    write(PREFIX + '-' + kind + '-result.json', record)
    print(json.dumps(record))
    if result.returncode:
        print(read(log)[-16000:])
        sys.exit(result.returncode)


def check():
    baseline = obj(PREFIX + '-baseline.json')
    registration = obj(PREFIX + '-registration.json')
    changed = [f['path'] for f in baseline['files'] if digest(f['path']) != f['sha256']]
    assert changed == ['Hindman168.lean', 'Verification.lean']
    own = sorted(Path('Hindman168').glob('*.lean'))
    pnt = sorted(Path('PrimeNumberTheoremAnd').rglob('*.lean'))
    assert len(own) == 1180 and len(pnt) == 9
    assert set(str(p).replace('\\', '/') for p in own) == {
        f['path'] for f in baseline['files'] if f['path'].startswith('Hindman168/')} | set(MODULES)
    imports = re.findall(r'^import (Hindman168\.\S+)', old.lean_code(read('Hindman168.lean')), re.M)
    assert len(imports) == len(set(imports)) == len(own)
    assert set(imports) == {str(p.with_suffix('')).replace('\\', '.').replace('/', '.') for p in own}
    names = ['Hindman168.' + n for p, ds in declarations().items() for _, n in ds]
    assert names == registration['names'] and len(names) == 13
    for p in own + pnt + [Path('Hindman168.lean'), Path('Verification.lean')]:
        code = old.lean_code(read(p))
        assert not re.search(r'\b(?:sorry|admit|sorryAx|native_decide|implemented_by)\b', code), p
        assert not re.search(r'^\s*(?:(?:private|protected|noncomputable)\s+)*(?:axiom|unsafe)\b', code, re.M), p
    for p in MODULES:
        assert not re.search(r'\b(?:set_option|setOptions)\b', old.lean_code(read(p)))
        olean = Path('.lake/build/lib/lean') / Path(p).with_suffix('.olean')
        assert olean.stat().st_mtime_ns >= Path(p).stat().st_mtime_ns
    for kind, log in [('build', '-build.txt'), ('kernel', '-axioms.txt')]:
        result = obj(PREFIX + '-' + kind + '-result.json')
        assert result['terminal'] and result['exit_code'] == 0
        assert result['log_sha256'] == digest(PREFIX + log)
        assert result['command'] == (['lake', 'build'] if kind == 'build' else ['lake', 'env', 'lean', 'Verification.lean'])
        assert not re.search(r'(?:error:|warning:)', read(PREFIX + log))
    jobs = re.findall(r'Build completed successfully \((\d+) jobs\)\.', read(PREFIX + '-build.txt'))
    assert len(jobs) == 1 and int(jobs[0]) >= baseline['build_job_count'] + len(MODULES)
    previous, actual = old.reports(OLD + '-axioms.txt'), old.reports(PREFIX + '-axioms.txt')
    assert obj(OLD + '-kernel-result.json')['log_sha256'] == digest(OLD + '-axioms.txt')
    registered = re.findall(r'^#print axioms (\S+)', old.lean_code(read('Verification.lean')), re.M)
    assert len(registered) == len(set(registered)) == len(actual) == 5431
    assert set(registered) == set(actual)
    assert set(actual) - set(previous) == set(names)
    assert all(actual[n] == v for n, v in previous.items())
    assert all(v <= old.ALLOWED for v in actual.values())
    assert {n for n, v in actual.items() if not v} == old.AXIOM_FREE | {'Hindman168.intervalResidueParent', 'Hindman168.completeResidueCellPoint', 'Hindman168.integerCubeResidueShift', 'Hindman168.admissible_option_selection_none'}
    assert old.run(['git', '-C', '.lake/packages/mathlib', 'rev-parse', 'HEAD']) == baseline['mathlib_commit']
    assert old.run(['git', '-C', '../reference-pntplus', 'rev-parse', 'HEAD']) == baseline['pntplus_commit']
    lean = old.run(['lake', 'env', 'lean', '--version'])
    assert 'version 4.32.2,' in lean and 'f3b06c705e6c85f5314019d5d3baab0fec5b580c' in lean
    fixed = obj(OLD + '-preprint-local-check.json')
    assert fixed['fixed_openai_math_commit'] == baseline['openai_math_commit']
    for section in fixed['sections']:
        data = (Path('E:/codex-build/math') / section['path']).read_bytes().replace(b'\r\n', b'\n')
        pinned = subprocess.run(['git', '-C', 'E:/codex-build/math', 'show',
            fixed['fixed_openai_math_commit'] + ':' + section['path']], stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, check=True).stdout.replace(b'\r\n', b'\n')
        assert data == pinned and hashlib.sha256(data).hexdigest() == section['normalized_sha256']
    files = [{'path': f['path'], 'sha256': digest(f['path'])} for f in baseline['files']]
    files += [{'path': p, 'sha256': digest(p)} for p in MODULES]
    assert len(files) == len({f['path'] for f in files}) == 1198
    summary = dict(project_modules=len(own), pntplus_modules=len(pnt), source_scan_modules=len(own)+len(pnt),
        source_config_hashes=len(files), build_jobs=int(jobs[0]), axiom_reports=len(actual),
        new_theorems=9, new_definitions=4, new_instances=0, new_axiom_reports=13, standard_axioms_only=True,
        retained_proof_sources_unchanged=True, retained_axiom_sets_unchanged=True,
        root_imports_exact=True, registered_kernel_names_exact=True, full_target_proved=False)
    return baseline, files, summary, fixed


def record():
    baseline, files, summary, fixed = check()
    review = dict(date='2026-10-10', classification='PROGRESS', full_target_proved=False,
        application_review=['PROGRESS. The preceding native local correlator synthesis and interval inverse projection implication round was terminal-successfully rechecked before edits. Its authoritative manifest was copied unchanged to this saved baseline. Retained proof-source hashes and selected kernel axiom sets remain unchanged, except the necessary root imports and declaration registry.', 'The original complete-cell mass sum is identified exactly with the original aligned interior mass at each admissible master stage. The retained admissible cell sum is applied to the constant one input, retaining the original harmonic integer coefficients, actual coprime residues and exact signed integer endpoints. Subtype, finite product and iterated sums are identified exactly. This is a finite-stage identity, not a substitution of the limiting value one.', 'Canonical definitions name the actual complete-cell mass, its actual total-normalized probability and the actual weighted global Gowers value in the M*q coordinates of the inverse argument. Exact divisibility gives M*(R/M)=R. Pointwise equality first proves equality of the full probability functions with the original aligned-interval formula; this function equality and exact coordinate identity then prove equality of both global norm formulas for every degree and every integer input.', 'For a fixed positive threshold theta, the retained rough-coprimality estimate gives original independent pair mean at most global norm + theta. If the original global norm is at most theta, this mean is at most 2*theta. The proved finite-mass weighted qualitative Bessel theorem bounds the actual conditioned prime-tuple local mean by the universal Bessel modulus at that budget. The displayed modulus bound, not an assumed Bessel conclusion, gives the requested local norm error.', 'The fixed-budget estimate is instantiated on the original master complete cells. Their exact probability identity transfers the proved original common-cell probability conditions to the canonical law. Actual positivity and original unit input are retained. The conditioned prime-tuple mass is exactly the original one, including its genuine support and normalization; no uniform tuple law replaces it.', 'The original short-cube estimate is integrated over that actual good prime-tuple law. Support supplies membership of the actual prime pools and nonvanishing of the polynomial. The subgroup finite-type instance is identified exactly before the short-cube estimate is used. The exact probability and coordinate identities align its local norm with the fixed-budget Bessel norm. The resulting bound retains (2J)^d*eta + 4d/J + xi and the original integerPredictionShortCubeStatistic.', 'The uniform short-cube theorem chooses a positive J from the requested error and short-cube dimension, then a positive universal Bessel budget from the local error epsilon/(4*(2J)^d), before introducing n, N, polynomial data, gap or pivot. The fixed-budget theorem supplies the later stage estimates for each chosen master system. Thus the constants are independent of master count and cell probabilities; the eventual stage may still depend on the selected arithmetic data, as in the paper.', 'HasNativePeriodicIntervalInverse is only an explicit unproved proposition. For each positive delta it requires a finite positive manifold list with actual native step bound, one Lipschitz constant per listed manifold and a positive correlation constant, all selected before q, K or the original unit real input. It quantifies the actual periodic interval norm at threshold delta/4 and actual complex linear orbit correlation. No instance, axiom or theorem asserting this proposition is introduced.', 'Given that displayed inverse proposition, a fixed delta selects the finite list and positive correlation constant before all master data. The actual fine projection threshold delta^(2^d)*gamma/2 is strictly positive. The preceding fully proved master projection threshold theorem therefore gives eventual canonical global norm below delta uniformly in N and all master parameters, on the same tail-containing ultrafilter and original integer harmonic Hilbert law.', 'The final conditional inverse short-cube theorem first chooses J and theta from d and epsilon by the uniform Bessel theorem, then the positive projection threshold at global order 2^d+2^d-1 from the displayed interval inverse input. Only afterwards does it introduce N, polynomial data, the original good-tuple law, gaps, ultrafilter and arbitrary actual unit Hilbert family. Small fine projection gives eventual canonical global norm < theta, hence <= theta; the actual original short-cube expectation is then < epsilon on that same ultrafilter. No cyclic statistic substitutes for the original integer statistic.', 'Development failures were resolved before registration. The probability equality is proved as a function equality before rewriting inside weighted norms; arithmetic expressions use the original divisibility identity. Unused proof binders in nested uniform statements are explicitly named with underscores, while all required hypotheses remain. One earlier failed build is excluded from evidence. Only warning-free terminal focused compilations, the complete successful build and complete selected kernel output count. No set_option or increased resource limit occurs in new source.', 'Six new modules contain nine theorems and four definitions, all selected for transitive kernel audit. The sixteen retained axiom-free declarations remain unchanged. This round proves exact law alignment and the uniform inverse-input-to-original-short-cube implication. The finite-list interval inverse existence proposition remains unproved, and StrongConjecture is unchanged and unproved. Remaining replica integration, coloring-derived targets, Calibration/Alignment and final positive rapidly separated monochromatic extraction remain. No unavoidable blocker is established; public repository, prize PR and claim remain pending.'], new_modules=MODULES, verified=summary, remaining=REMAINING,
        primary_reference='https://github.com/openai/math/tree/adc7f1241b42e322a6451854ab7e4b4c146bf78a', reference_scope='05_prediction: exact original cell-law alignment and uniform inverse short-cube threshold before choosing N')
    manifest = dict(baseline)
    manifest.update(files=files, hindman_module_count=1180, pntplus_module_count=9,
        selected_axiom_report_count=5431, source_scan_module_count=1189,
        build_job_count=summary['build_jobs'], build_log=PREFIX+'-build.txt', axiom_log=PREFIX+'-axioms.txt',
        last_round=dict(classification='PROGRESS', new_module_count=6, new_theorem_count=9,
            new_selected_report_count=13, retained_proof_sources_changed=False,
            root_and_registry_changed=True, review_file=PREFIX+'-review.json', remaining=REMAINING))
    manifest['proved_components'] = baseline['proved_components'] + COMPONENTS
    audit = read('AUDIT.txt')
    marker = 'Remaining proof work:'
    assert audit.count(marker) == 1
    assert audit.split(marker, 1)[1].strip() == baseline['last_round']['remaining']
    note = '\n2026-10-10 ' + PREFIX + ': PROGRESS. ' + ' '.join(COMPONENTS) + '\n'
    note += json.dumps(summary) + '\nReview: ' + PREFIX + '-review.json\n\n'
    Path('AUDIT.txt').write_text(audit.split(marker, 1)[0]+note+marker+'\n'+REMAINING+'\n', encoding='utf-8')
    Path('BUILD-EVIDENCE.txt').write_bytes(b'=== COMPLETE BUILD OUTPUT ===\n' +
        Path(PREFIX+'-build.txt').read_bytes()+b'\n=== COMPLETE AXIOM OUTPUT ===\n'+
        Path(PREFIX+'-axioms.txt').read_bytes()+b'\n')
    write(PREFIX+'-review.json', review)
    write('verification-manifest.json', manifest)
    write(PREFIX+'-preprint-local-check.json', fixed)
    write(PREFIX+'-checks.json', summary)
    print(json.dumps(summary))


def recheck():
    _, files, summary, _ = check()
    manifest = obj('verification-manifest.json')
    assert manifest['files'] == files and manifest['last_round']['remaining'] == REMAINING
    assert obj(PREFIX+'-review.json')['verified'] == summary
    assert read('AUDIT.txt').split('Remaining proof work:', 1)[1].strip() == REMAINING
    assert Path('BUILD-EVIDENCE.txt').read_bytes() == b'=== COMPLETE BUILD OUTPUT ===\n' + \
        Path(PREFIX+'-build.txt').read_bytes()+b'\n=== COMPLETE AXIOM OUTPUT ===\n'+ \
        Path(PREFIX+'-axioms.txt').read_bytes()+b'\n'
    print(json.dumps(summary))


if __name__ == '__main__':
    sys.stdout.reconfigure(encoding='utf-8')
    mode = sys.argv[1]
    if mode == 'register': register()
    elif mode in {'build', 'kernel'}: run_build(mode)
    elif mode == 'record': record()
    elif mode == 'recheck': recheck()
    else: raise ValueError(mode)
